solutionCode:
pub struct Item {
    pub nome: String,
    pub quantidade: i32,
}

pub fn item_do(nome: String, quantidade: i32) -> Item {
    Item { nome, quantidade }
}

impl Item {
    pub fn linha(&self) -> String {
        format!("{}: {} unidades", self.nome, self.quantidade)
    }
}

pub fn relatorio_de(nome: String, quantidade: i32) -> String {
    Item { nome, quantidade }.linha()
}

testsCode:
use desafio::relatorio_de;

#[test]
fn testa_o_relatorio_do_parafuso() {
    assert_eq!(relatorio_de(String::from("parafuso"), 30), "parafuso: 30 unidades");
}

#[test]
fn testa_o_relatorio_da_porca() {
    assert_eq!(relatorio_de(String::from("porca"), 12), "porca: 12 unidades");
}
